     1	\section{Complex tori}
     2	\label{mumford-I1}
     3	\dcref{M:ch1:I.1}
     4	
     5	\begin{convention}[Analytic standing hypotheses]
     6	\label{mumford-conv-complex-analytic}
     7	\dcref{M:ch1:I.1}
     8	Throughout this chapter $V$ is a complex vector space of dimension $g$ and
     9	$\Lambda\subset V$ is a discrete subgroup spanning $V$ over $\C$.  A complex
    10	torus is the quotient $V/\Lambda$ with its quotient complex structure.  A
    11	compact connected complex Lie group is always understood to have holomorphic
    12	multiplication and inverse.
    13	\notready
    14	\end{convention}
    15	
    16	\begin{lemma}[Compactness of a lattice quotient]
    17	\label{mumford-lem-compact-lattice-quotient}
    18	\dcref{M:ch1:I.1}
    19	If $\Lambda$ is a lattice in $V$, then $V/\Lambda$ is a compact connected
    20	complex manifold of dimension $g$, and the quotient map is a holomorphic
    21	covering with deck group $\Lambda$.
    22	\notready
    23	\end{lemma}
    24	
    25	\begin{lemma}[Compact holomorphic functions]
    26	\label{mumford-lem-compact-holomorphic-functions}
    27	\dcref{M:ch1:I.1}
    28	Every holomorphic map from a compact connected complex manifold to $\C$ is
    29	constant.  Consequently a holomorphic map from a compact connected manifold
    30	to a finite-dimensional complex vector space is constant.
    31	\begin{proof}
    32	The absolute value of each coordinate function attains a maximum.  The maximum
    33	principle makes each coordinate locally, hence globally, constant on the
    34	connected manifold.
    35	\end{proof}
    36	\notready
    37	\end{lemma}
    38	
    39	\begin{theorem}[Uniformization of compact complex Lie groups]
    40	\label{mumford-thm-complex-lie-uniformization}
    41	\dcref{M:ch1:I.1}
    42	Let $X$ be a compact connected complex Lie group with identity $e$ and let
    43	$V=\Lie_e(X)$.  The exponential homomorphism $\exp:V\to X$ is surjective,
    44	its kernel $\Lambda$ is a lattice in $V$, and $\exp$ induces an isomorphism
    45	of complex Lie groups $V/\Lambda\simeq X$.  In particular $X$ is commutative.
    46	\uses{mumford-conv-complex-analytic,mumford-lem-compact-holomorphic-functions}
    47	\notready
    48	\end{theorem}
    49	
    50	\begin{proposition}[Linear description of homomorphisms]
    51	\label{mumford-prop-torus-homomorphisms}
    52	\dcref{M:ch1:I.1}
    53	For complex tori $X=V/\Lambda$ and $Y=W/\Gamma$, every holomorphic group
    54	homomorphism $X\to Y$ has a unique complex-linear lift $u:V\to W$ with
    55	$u(\Lambda)\subseteq\Gamma$.  Conversely every such $u$ descends to a
    56	holomorphic group homomorphism.  Thus
    57	\[
    58	  \Hom(X,Y)=\{u\in\Hom_\C(V,W):u(\Lambda)\subseteq\Gamma\}.
    59	\]
    60	\uses{mumford-thm-complex-lie-uniformization}
    61	\notready
    62	\end{proposition}
    63	
    64	\begin{corollary}[Topological cohomology of a torus]
    65	\label{mumford-cor-torus-cohomology}
    66	\dcref{M:ch1:I.1}
    67	For $X=V/\Lambda$, the singular cohomology ring with integral coefficients is
    68	canonically
    69	\[
    70	 H^\bullet(X,\Z)\simeq \bigwedge^\bullet\Hom_\Z(\Lambda,\Z),
    71	\]
    72	and the fundamental group is $\pi_1(X)\simeq\Lambda$.
    73	\uses{mumford-lem-compact-lattice-quotient}
    74	\notready
    75	\end{corollary}
    76	
    77	\section{Line bundles on a complex torus}
    78	\label{mumford-I2}
    79	\dcref{M:ch1:I.2}
    80	
    81	\begin{definition}[Factor of automorphy]
    82	\label{mumford-def-factor-automorphy}
    83	\dcref{M:ch1:I.2}
    84	Let $X=V/\Lambda$.  A factor of automorphy is a holomorphic function
    85	$a:\Lambda\times V\to\C^\times$ satisfying
    86	\[
    87	 a(\lambda+\mu,z)=a(\lambda,z+\mu)a(\mu,z).
    88	\]
    89	It defines a line bundle $L_a$ by identifying $(z,t)$ with
    90	$(z+\lambda,a(\lambda,z)t)$ on $V\times\C$.

