    51	\begin{lemma}[Rigidity Lemma, Form I]
    52	\label{mumford-lem-rigidity-form-I}
    53	Let $X$ be complete and let $Y,Z$ be varieties.  If
    54	$f:X\times Y\to Z$ is a morphism and there are $y_0\in Y$, $z_0\in Z$ with
    55	$f(X\times\{y_0\})=\{z_0\}$, then there is a unique morphism $g:Y\to Z$ such
    56	that $f=g\circ p_2$.
