   365	\label{mumford-iv23-theta-group-triviality}
   366	For a finite theta group of prime exponent, the commutator pairing controls
   367	whether a subgroup is central and whether the extension splits locally.
   368	\dcref{M:ch4:IV.23}
   369	\uses{mumford-def-theta-group,mumford-prop-theta-commutator}
   370	\notready
   371	\end{lemma}
   372	
   373	\begin{theorem}[Line-bundle theta group]
   374	\label{mumford-iv23-line-bundle-theta-group}
   375	Automorphisms of a line bundle over translations form the central extension
   376	$1\to\Gm\to\mathcal G(L)\to K(L)\to1$.
   377	\dcref{M:ch4:IV.23}
   378	\uses{mumford-def-theta-group}
   379	\notready
   380	\end{theorem}
   381	
   382	\begin{definition}[Divisor description of a theta group]
   383	\label{mumford-iv23-divisor-description}
   384	Choosing a divisor representative for $L$ identifies theta-group elements with
   385	translation/divisor pairs and makes the commutator explicit.
   386	\dcref{M:ch4:IV.23}
   387	\uses{mumford-iv23-line-bundle-theta-group}
   388	\notready
   389	\end{definition}
   390	
   391	\begin{theorem}[Theta lifting and descent]
   392	\label{mumford-iv23-isogeny-lifting-theorem}
   393	Descent of $L$ along an isogeny is equivalent to lifting its kernel into the
   394	theta group; the descended bundle has the expected pullback.
   395	\dcref{M:ch4:IV.23}
   396	\uses{mumford-iv23-line-bundle-theta-group,mumford-prop-abelian-quotient}
   397	\notready
   398	\end{theorem}
   399	
   400	\begin{theorem}[Power criterion for line bundles]
   401	\label{mumford-iv23-power-criterion}
   402	For nondegenerate $L$, containment of $A[n]$ in $K(L)$ is equivalent to $L$
   403	being an $n$th tensor power after the corresponding descent obstruction
   404	vanishes.
   405	\dcref{M:ch4:IV.23}
   406	\uses{mumford-iv23-isogeny-lifting-theorem,mumford-prop-multiplication-n}
   407	\notready
   408	\end{theorem}
   409	
   410	\begin{theorem}[Maximal isotropic theta subgroup]
   411	\label{mumford-iv23-maximal-isotropic-theorem}
   412	For a nondegenerate theta group, a maximal isotropic subgroup equals its
   413	commutator orthogonal and has square-root order in $K(L)$; this controls
   414	principal polarizations and the irreducible theta representation.
   415	\dcref{M:ch4:IV.23}
   416	\uses{mumford-prop-theta-commutator,mumford-thm-theta-representation}
   417	\notready
   418	\end{theorem}
   419	
   420	\begin{definition}[Analytic theta extension]
   421	\label{mumford-iv24-analytic-theta-extension}
   422	For a complex torus and Hermitian form $H$, automorphisms of the factor of
   423	automorphy form a central Heisenberg extension whose commutator is determined
   424	by $\operatorname{Im}H$ on the lattice.
   425	\dcref{M:ch4:IV.24}

