   620	\section[Theta groups]{The theta group of a line bundle}
   621	\label{mumford-IV23}
   622	\dcref{M:ch4:IV.23}
   623	
   624	\begin{definition}[Theta group]
   625	\label{mumford-def-theta-group}
   626	\dcref{M:ch4:IV.23}
   627	For a line bundle $L$ on $A$, the theta group $\mathcal G(L)$ is the group
   628	scheme whose $S$-points are pairs $(x,\varphi)$ with $x\in K(L)(S)$ and
   629	$\varphi:L_S\xrightarrow{\sim}t_x^*L_S$.  There is an exact sequence
   630	\[
   631	 1\longrightarrow\Gm\longrightarrow\mathcal G(L)\longrightarrow K(L)
   632	 \longrightarrow1.
   633	\]
   634	\uses{mumford-def-KL}
   635	\notready
   636	\end{definition}
   637	
   638	\begin{proposition}[Theta commutator]
   639	\label{mumford-prop-theta-commutator}
   640	\dcref{M:ch4:IV.23}
   641	The commutator in the theta group is the alternating pairing
   642	\[
   643	 e^L:K(L)\times K(L)\to\Gm
   644	\]
   645	induced by the biextension of $L$.  If $L$ is nondegenerate, this pairing is
   646	perfect and $|K(L)|$ is a square.
   647	\uses{mumford-def-theta-group,mumford-def-biextension}
   648	\notready
   649	\end{proposition}
   650	
   651	\begin{theorem}[Theta representation]
   652	\label{mumford-thm-theta-representation}
   653	When $L$ is ample, $\mathcal G(L)$ acts on $H^0(A,L)$.  Every irreducible
   654	representation on which the central $\Gm$ acts by its tautological character
   655	has dimension $h^0(A,L)$ and is unique up to isomorphism; the natural action on
   656	$H^0(A,L)$ is that representation.
   657	\dcref{M:ch4:IV.23}
   658	\uses{mumford-prop-theta-commutator,mumford-thm-line-bundle-index}
   659	\notready
   660	\end{theorem}
