    21	$\underline{\operatorname{Aut}}(L/X)\simeq\mathcal G(L)$.
    22	\source{mumford-abelian-varieties:page-0237}
    23	\source{mumford-abelian-varieties:page-0238}
    24	\end{proof}
    25	
    26	\begin{definition}[Commutator pairing of a line bundle]
    27	\label{mumford-def-line-bundle-commutator}
    28	The theta group $\mathcal G(L)$ has a skew-symmetric bihomomorphism
    29	\[
    30	e^L:K(L)\times K(L)\to\mathbb G_m
    31	\]
    32	defined by its commutator. If $L\in\operatorname{Pic}^0X$, then $K(L)=X$,
    33	so $e^L=1$ and $\mathcal G(L)$ is commutative.
    34	\source{mumford-abelian-varieties:page-0238}
    35	\end{definition}
    36	
    37	\begin{proposition}[Functoriality of commutator pairings]
    38	\label{mumford-prop-line-bundle-commutator-functorial}
    39	For homomorphisms and line bundles as indicated,
    40	\begin{enumerate}
    41	\item $e^{f^*L}(x,y)=e^L(fx,fy)$;
    42	\item $e^{L_1\otimes L_2}(x,y)=e^{L_1}(x,y)e^{L_2}(x,y)$;
    43	\item algebraically equivalent line bundles have equal pairings;
    44	\item $e^{L^n}(x,y)=e^L(x,ny)$ for $x\in K(L)$,
    45	$y\in n_X^{-1}K(L)$;
    46	\item if $x\in X_n$ and $y\in\phi_L^{-1}(X_n)$, then
    47	$\bar e_n(x,\phi_L(y))=e^{L^n}(x,y)$.
    48	\end{enumerate}
    49	\source{mumford-abelian-varieties:page-0239}
    50	\source{mumford-abelian-varieties:page-0240}
    51	\source{mumford-abelian-varieties:page-0241}
    52	\end{proposition}
    53	\begin{proof}
    54	Lift $f(x),f(y)$ to automorphisms in the theta group; their commutator
    55	proves (1). Tensoring liftings proves (2), and (3) follows by writing
    56	$L_1=L_2\otimes L_3$ with $L_3\in\operatorname{Pic}^0X$. For (4), after a
    57	faithfully flat extension write $x=nz$; then
    58	\[
    59	e^L(nz,ny)=e^{n_X^*L}(z,y)=e^{L^{n^2}}(z,y)
    60	=(e^{L^n}(z,y))^n=e^{L^n}(nz,y).
    61	\]
    62	For (5), write $y=nz$ and compare
    63	$n_X^*(T_y^*L\otimes L^{-1})$ with
    64	the line bundle $\operatorname{Hom}[n_X^*L,T_{ny}^*n_X^*L]$. The action of $x\in X_n$ on
    65	the resulting nowhere-vanishing section is conjugation by the natural
    66	translation isomorphism; this is simultaneously the Weil pairing and the
    67	theta-group commutator.
    68	\end{proof}
    69	
    70	\begin{theorem}[Descent of line bundles]
    71	\label{mumford-thm-theta-descent}
    72	For an isogeny $\pi:X\to Y$ and a line bundle $L$ on $X$, line bundles $M$
    73	on $Y$ with $\pi^*M\simeq L$ correspond naturally to homomorphisms
    74	$\alpha:\ker\pi\to\mathcal G(L)$ lifting the inclusion into $X$.
    75	Such an $M$ exists iff $\ker\pi\subset K(L)$ and
    76	$e^L$ is trivial on $\ker\pi\times\ker\pi$.
    77	\source{mumford-abelian-varieties:page-0242}
    78	\uses{mumford-def-line-bundle-commutator}
    79	\end{theorem}
    80	\begin{proof}
    81	This is the finite-group-scheme descent theorem applied to the action of
    82	$\ker\pi$ on $L$. The lift is a splitting of the inverse image theta group.
    83	That theta group splits iff it is commutative, equivalently iff the
    84	commutator pairing is trivial.
    85	\end{proof}
    86	
    87	\begin{theorem}[Power criterion]
    88	\label{mumford-thm-line-bundle-power-criterion}
    89	For a line bundle $L$ and integer $n$, $L\simeq M^n$ for some $M$ iff
    90	$K(L)\supset X_n$.
    91	\source{mumford-abelian-varieties:page-0242}
    92	\source{mumford-abelian-varieties:page-0243}
    93	\end{theorem}
    94	\begin{proof}
    95	The forward implication follows from $\phi_{M^n}=n\phi_M$. Conversely,
    96	$K(L)\supset X_n$ gives
    97	$e^{L^n}(x,y)=e^L(x,ny)=1$ for $x,y\in X_n$. The descent criterion gives
    98	$L^n\simeq n_X^*N$; then $(L\otimes N^{-n})^n\in\operatorname{Pic}^0X$.
    99	Divisibility of $\operatorname{Pic}^0X$ supplies $P$ with
   100	$L\otimes N^{-n}\simeq P^n$, hence $L\simeq(N\otimes P)^n$.
   101	\end{proof}
   102	
   103	\begin{lemma}[Orthogonal subgroup]
   104	\label{mumford-lem-theta-orthogonal-subgroup}
   105	For a skew bihomomorphism $e:K\times K\to\mathbb G_m$ and subgroup $H$,
   106	$H^\perp$ is the kernel of $K\xrightarrow\gamma\widehat K\to\widehat H$;
   107	equivalently it consists of points pairing trivially with every base change of
   108	every point of $H$. If $L=\pi^*M$ and $H=\ker\pi$, then
   109	$K(M)\simeq H^\perp/H$.
   110	\source{mumford-abelian-varieties:page-0243}
   111	\source{mumford-abelian-varieties:page-0244}
   112	\end{lemma}
   113	\begin{proof}
   114	The kernel description is immediate from restriction of characters. Locally
   115	on a base $S$, descent identifies $\pi x\in K(M)$ with an isomorphism of
   116	$T_x^*L$ with $L$ commuting with the $H$-action. A lift $w$ of $x$ in
   117	$\mathcal G(L)$ commutes with that action exactly when
   118	$e^L(x,h)=1$ for all $h\in H$, which is $x\in H^\perp$.
   119	\end{proof}
   120	
   121	\begin{theorem}[Maximal isotropic subgroup]
   122	\label{mumford-thm-maximal-isotropic-theta}
   123	If $L$ is non-degenerate and $H\subset K(L)$ is maximal with
   124	$e^L|_{H\times H}=1$, then $H=H^\perp$ and
   125	\[
   126	\operatorname{order}(H)^2=\operatorname{order}(K(L)).
   127	\]
   128	\source{mumford-abelian-varieties:page-0244}
   129	\source{mumford-abelian-varieties:page-0245}
   130	\end{theorem}
   131	\begin{proof}
   132	Put $Y=X/H$ and $L=\pi^*M$. Maximality means $M$ admits no nontrivial
   133	further descent. If a non-degenerate bundle admits no descent of degree
   134	$>1$, then $|\chi(M)|=1$: otherwise a prime-order subgroup of $K(M)$,
   135	whose theta extension is commutative, would give a descent. Hence
   136	$K(M)=0$ and $|\chi(M)|=1$. The orthogonal lemma gives $H=H^\perp$; and
   137	Riemann--Roch gives
   138	$|\chi(L)|=\operatorname{order}(H)$ and
   139	$\chi(L)^2=\operatorname{order}(K(L))$.
   140	\end{proof}
   141	
   142	\begin{corollary}[Principal polarization and non-degeneracy]
   143	\label{mumford-cor-principal-polarization-theta}
   144	Every abelian variety is isogenous to a principally polarized one. If $L$ is
   145	non-degenerate, then $\mathcal G(L)$ is a non-degenerate theta group.
   146	\source{mumford-abelian-varieties:page-0245}
   147	\source{mumford-abelian-varieties:page-0246}
   148	\uses{mumford-thm-maximal-isotropic-theta}
   149	\end{corollary}
   150	\begin{proof}
   151	Apply the theorem to an ample $L$ and descend to $X/H$; the descended bundle
   152	has Euler characteristic one. For the second assertion, let $D$ be the
   153	kernel of the commutator map $\gamma$. If $H=H^\perp$, then $D\subset H$ and
   154	the image of $K(L)$ in $\widehat H$ has kernel $D$. Therefore
   155	\[
   156	\operatorname{order}K(L)\leq\operatorname{order}H\cdot
   157	\operatorname{order}(\widehat H/D)=
   158	\frac{\operatorname{order}(H)^2}{\operatorname{order}D}.
   159	\]
   160	Since $\operatorname{order}K(L)=\operatorname{order}(H)^2$, $D=1$.
   161	\end{proof}

